files.content:
:root {
  --bg: #1a1c2c;
  --panel: #2b2d42;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #a0a3b1;
  --error: #ef476f;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--panel);
  padding: 24px;
  border-radius: 8px;
  box-shadow: 0 0 0 4px var(--bg), 0 0 0 8px var(--accent), 0 12px 24px rgba(0, 0, 0, 0.4);
  image-rendering: pixelated;
}

h1 {
  margin: 0 0 20px;
  font-size: 1.5rem;
  text-align: center;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}

.field {
  margin-bottom: 16px;
}

label {
  display: block;
  margin-bottom: 6px;
  font-size: 1rem;
  color: var(--muted);
}

input,
select,
button {
  width: 100%;
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 12px;
  border: 2px solid var(--bg);
  border-radius: 4px;
  background: var(--bg);
  color: var(--text);
  transition: border-color 0.15s, background 0.15s, transform 0.05s;
}

input:focus,
select:focus,
button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}

input:hover,
select:hover {
  border-color: var(--accent);
}

button {
  margin-top: 8px;
  background: var(--accent);
  color: var(--bg);
  font-weight: 700;
  cursor: pointer;
  border-color: var(--accent);
}

button:hover {
  background: #ffe08a;
}

button:active {
  transform: translateY(2px);
  background: #e6b85c;
}

.result-box {
  margin-top: 20px;
  padding: 16px;
  background: var(--bg);
  border-radius: 4px;
  text-align: center;
}

.result-label {
  display: block;
  font-size: 0.85rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 6px;
}

#result {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--accent);
  word-break: break-all;
}

#result.error {
  color: var(--error);
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
    box-shadow: 0 0 0 3px var(--bg), 0 0 0 6px var(--accent);
  }
  h1 {
    font-size: 1.25rem;
  }
}

const leftInput = document.getElementById('left');
const rightInput = document.getElementById('right');
const operationSelect = document.getElementById('operation');
const calculateButton = document.getElementById('calculate');
const resultOutput = document.getElementById('result');

function showError() {
  resultOutput.textContent = 'Error';
  resultOutput.classList.add('error');
}

function showResult(value) {
  resultOutput.textContent = String(value);
  resultOutput.classList.remove('error');
}

function parseNumber(input) {
  const raw = input.value.trim();
  if (raw === '') return null;
  const num = Number(raw);
  if (!Number.isFinite(num)) return null;
  return num;
}

function calculate() {
  const left = parseNumber(leftInput);
  const right = parseNumber(rightInput);

  if (left === null || right === null) {
    showError();
    return;
  }

  const operation = operationSelect.value;
  let result;

  switch (operation) {
    case 'add':
      result = left + right;
      break;
    case 'subtract':
      result = left - right;
      break;
    case 'multiply':
      result = left * right;
      break;
    case 'divide':
      if (right === 0) {
        showError();
        return;
      }
      result = left / right;
      break;
    default:
      showError();
      return;
  }

  if (!Number.isFinite(result)) {
    showError();
    return;
  }

  showResult(result);
}

calculateButton.addEventListener('click', calculate);

[leftInput, rightInput, operationSelect].forEach((control) => {
  control.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      calculate();
    }
  });
});
